for (const [word, ipa, expected] of cases) {
  assert.deepEqual(range(word, ipa), expected, word);
  assert.deepEqual(range(word.toUpperCase(), ipa), expected, word + ' uppercase');
  const [a, b] = expected;
  assert.equal(render(word, ipa, s => s), word.slice(0,a) + '<span class="spelling-stress">' + word.slice(a,b) + '</span>' + word.slice(b));
  assert.deepEqual(range(word, '/different/'), infer(word, '/different/'), word + ' reading guard');
}
assert.deepEqual(range('minute', '/maɪˈnjuːt/'), [3,4]);
assert.equal(range('minute', '/mɪnɪt/'), null);
assert.equal(range('hire', '/haɪər/ junk'), null);
